contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bool asOwner) public payable {
        uint beforeBalance = address(c).balance;
        uint beforeCount = c.depositsCount();

        bool reverted;
        if (asOwner) {
            try c.withdrawAll() {
                reverted = false;
            } catch {
                reverted = true;
            }

            assert(!reverted && address(c).balance == 0 && c.depositsCount() == beforeCount);
        } else {
            try c.withdrawAll() {
                reverted = false;
            } catch {
                reverted = true;
            }

            assert(reverted && address(c).balance == beforeBalance && c.depositsCount() == beforeCount);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bool asOwner) public payable {
        uint beforeBalance = address(c).balance;
        uint beforeCount = c.depositsCount();
        require(address(this).balance >= 0);

        bool reverted;
        if (asOwner) {
            (bool ok, ) = address(c).call{value: 0}(abi.encodeWithSignature("withdrawAll()"));
            reverted = !ok;
            assert(!reverted && address(c).balance == 0 && c.depositsCount() == beforeCount);
        } else {
            c.withdrawAll();
            reverted = false;
            assert(!reverted && address(c).balance == beforeBalance && c.depositsCount() == beforeCount);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint sendAmount, uint depositTries, bool doDeposit) public payable {
        require(address(this).balance >= sendAmount);

        // Drive c's state through public entry points so the rule is non-trivial.
        uint sentToC = 0;
        if (doDeposit) {
            (bool ok, ) = address(c).call{value: sendAmount}("");
            require(ok);
            sentToC = sendAmount;
        }

        uint beforeCount = c.depositsCount();
        require(depositTries == beforeCount || depositTries <= beforeCount);

        // Deciding call: withdrawAll must go through one top-level statement.
        c.withdrawAll();

        assert(address(c).balance == 0 && c.depositsCount() == beforeCount);
    }

    receive() external payable {}
}

