    function run(address target, uint value, uint amount) public payable {
        require(address(this).balance >= amount);
        require(target != address(0));

        uint beforeBalance = address(c).balance;
        uint beforeCount = c.depositsCount();
        address owner = c.owner();
        bool callerIsOwner = (address(this) == owner);

        bool reverted;
        try c.sendMoney(target, value) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (callerIsOwner) {
            assert(!reverted);
            assert(address(c).balance == beforeBalance - value);
            assert(c.depositsCount() == beforeCount);
        } else {
            assert(reverted);
            assert(address(c).balance == beforeBalance);
            assert(c.depositsCount() == beforeCount);
        }
    }
