        assert(reverted == (value > cBalanceBefore) && (reverted || cBalanceAfter == cBalanceBefore - value) && depositsAfter == depositsBefore);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address target, uint value) public payable {
        require(address(this).balance >= value, "insufficient balance");

        uint depositsBefore = c.depositsCount();
        uint cBalanceBefore = address(c).balance;

        bool reverted;
        try c.sendMoney(target, value) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint depositsAfter = c.depositsCount();
        uint cBalanceAfter = address(c).balance;

        assert(!reverted && depositsAfter == depositsBefore && cBalanceAfter <= cBalanceBefore && cBalanceAfter + value >= cBalanceBefore);
