}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint depositValue, uint withdrawAmount) public payable {
        require(address(this).balance >= depositValue + withdrawAmount + 0, "insufficient test balance");

        uint beforeBalance = address(c).balance;
        uint beforeCount = c.depositsCount();

        (bool depositSuccess, ) = address(c).call{value: depositValue}("");
        require(depositSuccess, "deposit failed");

        uint afterDeposit = address(c).balance;
        require(afterDeposit == beforeBalance + depositValue, "deposit accounting");

        (bool withdrawSuccess, ) = address(c).call(abi.encodeWithSignature("withdrawAll()"));

        uint afterBalance = address(c).balance;
        uint afterCount = c.depositsCount();

        bool balanceIsZero = afterDeposit == 0;

        assert(
            (balanceIsZero && withdrawSuccess && afterBalance == 0 && afterCount == beforeCount + 1) ||
            (!balanceIsZero && withdrawSuccess && afterBalance == afterDeposit - withdrawAmount && afterCount == beforeCount + 1) ||
            (!balanceIsZero && !withdrawSuccess && afterBalance == afterDeposit && afterCount == beforeCount + 1)
        );
    }

    receive() external payable {}
}

